# Homebrew formula for riddlc - the RIDDL compiler
# To install: brew install ossuminc/tap/riddlc
# Or add the tap first: brew tap ossuminc/tap && brew install riddlc
# Auto-generated by update-formula.yml - do not edit manually

class Riddlc < Formula
  desc "Compiler for RIDDL (Reactive Interface to Domain Definition Language)"
  homepage "https://github.com/ossuminc/riddl"
  version "2.5.0"
  license "Apache-2.0"

  # riddlc and riddlc-rc are mutually exclusive rather than the RC being
  # keg_only: a release candidate exists to be exercised as `riddlc` on
  # PATH, which a keg_only formula would not be.
  conflicts_with "riddlc-rc", because: "both install a riddlc binary"

  if OS.mac? && Hardware::CPU.arm?
    url "https://github.com/ossuminc/riddl/releases/download/#{version}/riddlc-macos-arm64.zip"
    sha256 "ca62b450e8129661a32ccb8b5a38cc3012c198ba34a4e3e93826dd9c65573222"
    depends_on "libidn2"
    depends_on "openssl@4"
  elsif OS.linux? && Hardware::CPU.intel?
    url "https://github.com/ossuminc/riddl/releases/download/#{version}/riddlc-linux-x86_64.zip"
    sha256 "a048cc7b4c680d8f91b26cdbce9b10ed26d9d2c87d21178ac6b82abdf22a5fbc"
    depends_on "libidn2"
    depends_on "openssl@3"
  else
    url "https://github.com/ossuminc/riddl/releases/download/#{version}/riddlc.zip"
    sha256 "9e8fb8b0725759c8e42ca518e3f3a8e769a397dc8caea5ab23abba29c0017843"
    depends_on "openjdk@21"
  end

  def install
    if (OS.mac? && Hardware::CPU.arm?) || (OS.linux? && Hardware::CPU.intel?)
      # Native binary - Homebrew strips the single top-level "bin/" dir
      bin.install "riddlc"
    else
      # JVM version - needs wrapper script
      rm "bin/riddlc.bat"
      libexec.install "lib"
      libexec.install "bin"

      (bin/"riddlc").write <<~EOS
        #!/bin/bash
        export JAVA_HOME="#{Formula["openjdk@21"].opt_prefix}"
        exec "#{libexec}/bin/riddlc" "$@"
      EOS
    end
  end

  def caveats
    if (OS.mac? && Hardware::CPU.arm?) || (OS.linux? && Hardware::CPU.intel?)
      <<~EOS
        riddlc is installed as a native binary. No JDK required.

        To verify the installation and see what you got:
          riddlc info

        For help:
          riddlc help
      EOS
    else
      <<~EOS
        riddlc requires Java 21. This formula uses openjdk@21.

        To verify the installation and see what you got:
          riddlc info

        For help:
          riddlc help
      EOS
    end
  end

  test do
    # `riddlc info` proves the binary runs AND that it reports the
    # version this formula claims to have installed.
    assert_match version.to_s, shell_output("#{bin}/riddlc info")
  end
end
